# update code in file via write; task transform: axis lines then components of 2 connected 4-neighbor touched by lines are fully 1
code='''def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    lines=[]
    for c in range(w):
        if out[0][c]==1 and out[-1][c]==1: lines.append(("c",c))
    for r in range(h):
        if out[r][0]==1 and out[r][-1]==1: lines.append(("r",r))
    touched=set()
    for typ,n in lines:
        for i in range(h if typ=="c" else w):
            r,c=(i,n) if typ=="c" else (n,i)
            out[r][c]=1
            if grid[r][c]==2: touched.add((r,c))
    seen=set()
    for pos in touched:
        if pos in seen: continue
        stack=[pos]; comp=[]; seen.add(pos)
        while stack:
            r,c=stack.pop(); comp.append((r,c))
            for rr,cc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if 0<=rr<h and 0<=cc<w and grid[rr][cc]==2 and (rr,cc) not in seen:
                    seen.add((rr,cc)); stack.append((rr,cc))
        for r,c in comp: out[r][c]=1
    return out
'''
p.write_text(code)
spec=importlib.util.spec_from_file_location('task',p); mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
out=mod.transform(grid)
print(out)
